package cli

import (
	"fmt"
	"time"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

func newWatchDigestCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:         "digest",
		Short:       "See everything that changed across your whole watchlist since the last check.",
		Long:        "Compares the two most recent price observations for every watched product and reports price deltas and threshold crossings. Reads only local data — run 'watch check' first to refresh prices.",
		Example:     "  flipkart-pp-cli watch digest",
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			db, err := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if err != nil {
				return fmt.Errorf("opening local database: %w", err)
			}
			defer db.Close()
			if err := db.EnsureFlipkartSchema(); err != nil {
				return err
			}

			watches, err := db.ListFlipkartWatches()
			if err != nil {
				return fmt.Errorf("listing watches: %w", err)
			}
			if len(watches) == 0 {
				return printJSONFiltered(cmd.OutOrStdout(), map[string]any{
					"status":  "no_watches",
					"message": "no watches configured yet. Run 'watch add <product-url> --threshold <price>' first.",
				}, flags)
			}

			entries := make([]map[string]any, 0, len(watches))
			for _, w := range watches {
				history, err := db.LatestFlipkartPriceHistory(w.ProductID, 2)
				if err != nil {
					return fmt.Errorf("reading price history for %s: %w", w.ProductID, err)
				}
				entry := map[string]any{
					"product_id": w.ProductID,
					"url":        w.URL,
					"threshold":  w.Threshold,
				}
				if !w.LastCheckedAt.IsZero() {
					entry["last_checked_at"] = w.LastCheckedAt.UTC().Format(time.RFC3339)
				}
				if len(history) < 2 {
					entry["note"] = "fewer than 2 price checks recorded yet — run 'watch check' to start tracking changes"
					if len(history) == 1 {
						entry["current_price"] = history[0].Price
					}
					entries = append(entries, entry)
					continue
				}
				latest, prev := history[0], history[1]
				entry["current_price"] = latest.Price
				entry["previous_price"] = prev.Price
				entry["price_delta"] = latest.Price - prev.Price
				entry["at_or_below_threshold"] = w.Threshold > 0 && latest.Price <= w.Threshold
				entry["crossed_threshold_since_last_check"] = w.Threshold > 0 && latest.Price <= w.Threshold && prev.Price > w.Threshold
				entries = append(entries, entry)
			}

			return printJSONFiltered(cmd.OutOrStdout(), entries, flags)
		},
	}
	return cmd
}
